#![cfg(feature="player")]
#[path="support/audio_transitions.rs"]mod transitions;
#[path="support/rational_audio_seek.rs"]mod rational;
use fvid::{audio::AudioStream,playback_aiff::{AiffAudioReader,Limits}};
use std::{io::Cursor,time::Duration,sync::{Arc,Mutex}};
use rational::{Packet,collect,exact};
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/aiff-integer-precision")}
fn bytes(n:&str)->Vec<u8>{std::fs::read(root().join(n)).unwrap()}
fn cases()->Vec<serde_json::Value>{serde_json::from_slice::<serde_json::Value>(&bytes("manifest.json")).unwrap()["cases"].as_array().unwrap().clone()}
fn open(n:&str)->AiffAudioReader{let b=bytes(n);AiffAudioReader::open(b.as_slice(),Limits::default()).unwrap()}
fn expected(c:&serde_json::Value,first:usize)->Vec<Packet>{if first==2051{return vec![];}let channels=c["channels"].as_u64().unwrap()as u16;vec![Packet{rate:8000,channels,num:first as u128,den:8000,data:bytes(c["oracle"].as_str().unwrap())[first*usize::from(channels)*4..].to_vec()}]}
#[test]fn byte_width_and_neutral_video_controls(){for c in cases().into_iter().filter(|c|c["bits"].as_u64().unwrap()%8==0){exact(&collect(&mut open(c["file"].as_str().unwrap())),&expected(&c,0),"byte-aligned PCM control");}let mut v=fvid::playback_native::NativeReader::software(Cursor::new(bytes("neutral-video.mp4")),32<<20).unwrap();for _ in 0..6{assert_eq!(v.read_frame_raw().unwrap().unwrap().into_rgb(32<<20).unwrap(),vec![130;16*16*3]);}assert!(v.read_frame_raw().unwrap().is_none());}
#[test]fn all_integer_precisions_preserve_waveform_geometry_and_seek(){for c in cases(){let name=c["file"].as_str().unwrap();let mut r=open(name);assert_eq!(r.bits_per_sample(),c["bits"].as_u64().unwrap()as u16);assert_eq!(r.aiff().pcm.block_align(),c["stored_bytes"].as_u64().unwrap()as usize*c["channels"].as_u64().unwrap()as usize);assert_eq!(r.duration(),Some(Duration::from_micros(2051*125)));exact(&collect(&mut r),&expected(&c,0),name);for target in [-1,0,1,2047,2048,2050,2051,i64::MAX]{let first=target.clamp(0,2051)as usize;assert_eq!(r.seek_to(target),first as i64);exact(&collect(&mut r),&expected(&c,first),name);}for first in [1,2048,2051]{let at=r.seek_time(Duration::from_micros(first as u64*125));assert_eq!(r.time_of(at),Duration::from_micros(first as u64*125));exact(&collect(&mut r),&expected(&c,first),name);}assert_eq!(r.seek_time(Duration::MAX),2051);assert!(r.next_packet().unwrap().is_none());r.rewind();exact(&collect(&mut r),&expected(&c,0),"rewind");}}
#[test]fn actual_worker_decodes_nonbyte_precision_after_packet_boundary_seek(){use fvid::audio_thread::AudioPlayback;use transitions::{Capture,Trace,ended};for c in cases().into_iter().filter(|c|c["bits"].as_u64().unwrap()%8!=0){let raw=Arc::new(Mutex::new(rational::RawTrace::default()));let capture=raw.clone();let trace=Arc::new(Mutex::new(Trace::default()));let mut worker=AudioPlayback::start(Box::new(open(c["file"].as_str().unwrap())),move||Box::new(rational::RawCapture{inner:Capture::new(trace),raw:capture}));worker.seek(Duration::from_micros(2048*125));worker.play();ended(&worker,worker.generation());let got=raw.lock().unwrap();exact(&got.packets,&expected(&c,2048),c["file"].as_str().unwrap());assert_eq!(got.anchors,vec![Duration::from_micros(2048*125)]);}}
#[test]fn invalid_precision_stays_refused(){for bits in [0,33,65535]{let b=bytes(&format!("invalid-{bits}bit.aiff"));let error=AiffAudioReader::open(b.as_slice(),Limits::default()).err().expect("invalid sample size must refuse");assert!(error.to_string().contains(&format!("AIFF PCM of {bits} bits")),"{error}");}}
#[test]fn unused_bits_are_not_extra_precision_and_storage_padding_is_not_pcm(){for n in ["unused-low-bits-big.aiff","unused-low-bits-little.aiff"]{let b=bytes(n);let error=AiffAudioReader::open(b.as_slice(),Limits::default()).err().expect("dirty unused bits must refuse");assert!(error.to_string().contains("nonzero unused bits"),"{n}:{error}");}let mut r=open("padded-12bit.aiff");let want=vec![Packet{rate:8000,channels:1,num:0,den:1,data:[-1f32,2047f32/2048.].into_iter().flat_map(f32::to_le_bytes).collect()}];exact(&collect(&mut r),&want,"storage tail remains excluded");}
#[test]fn partial_frames_declared_eof_and_resource_admission_remain_strict(){let b=bytes("orphan-channel.aiff");let error=AiffAudioReader::open(b.as_slice(),Limits::default()).err().expect("orphan channel");assert!(error.to_string().contains("incomplete channel frame"),"{error}");let mut r=open("truncated-declared.aiff");while r.next_packet().unwrap().is_some(){}assert!(r.validate_eof().unwrap_err().to_string().contains("payload is truncated"));for c in cases(){let b=bytes(c["file"].as_str().unwrap());let mut limits=Limits::default();limits.data_bytes=2051*c["channels"].as_u64().unwrap()as usize*c["stored_bytes"].as_u64().unwrap()as usize-1;let error=AiffAudioReader::open(b.as_slice(),limits).err().expect("coded byte limit");assert!(error.to_string().contains("sample run is over"),"{error}");let mut limits=Limits::default();limits.file_bytes=b.len()-1;let error=AiffAudioReader::open(b.as_slice(),limits).err().expect("file limit");assert!(error.to_string().contains("file is over"),"{error}");}}
